from pathlib import Path
path = Path('/src/php-src/Zend/zend_operators.c')
data = path.read_text().splitlines(True)
# Find the zendi_try_get_long IS_STRING block and patch the remaining call.
for i,line in enumerate(data):
    if 'zend_incompatible_string_to_long_error(' in line and 'Z_STR_P(op)' in line:
        data[i] = line.replace('zend_incompatible_string_to_long_error(Z_STR_P(op))', 'zend_incompatible_string_to_long_error(str)')
        break
else:
    raise SystemExit('target call not found')

# Ensure zend_string_release(str) before returning lval in the double->long overflow branch.
# We'll look for the first 'return lval;' following that call within the IS_STRING block.
start = None
for i,line in enumerate(data):
    if 'case IS_STRING' in line:
        start = i
        break
if start is None:
    raise SystemExit('case IS_STRING not found')

call_idx = None
for i in range(start, min(start+200, len(data))):
    if 'zend_incompatible_string_to_long_error(str)' in data[i]:
        call_idx = i
        break
if call_idx is None:
    raise SystemExit('patched call not found')

# Find the matching return lval; after call_idx (this is the return from else branch)
for j in range(call_idx, min(call_idx+60, len(data))):
    if data[j].lstrip().startswith('return lval;'):
        # Insert release just before if not already present in previous non-empty line
        k = j-1
        while k > 0 and data[k].strip() == '':
            k -= 1
        if 'zend_string_release(str)' not in data[k]:
            indent = data[j].split('return')[0]
            data.insert(j, indent + 'zend_string_release(str);\n')
        break
else:
    raise SystemExit('return lval not found')

path.write_text(''.join(data))
print('Patched remaining pieces')
